def _knight_dist(a, b):
    # Plain BFS on the empty 50x50 board (pawns do not block the knight).
    if a == b:
        return 0
    seen = {a: 0}
    q = deque([a])
    while q:
        x, y = q.popleft()
        for dx, dy in KMOVES:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in seen:
                seen[(nx, ny)] = seen[(x, y)] + 1
                if (nx, ny) == b:
                    return seen[(nx, ny)]
                q.append((nx, ny))
    return None


