    return f"{kx}\n{ky}\n{json.dumps(cells)}\n"


def validate(inp):
    try:
        lines = inp.split("\n")
        # expected: three non-empty lines (trailing newline allowed)
        if len(lines) < 3:
            return False
        kx = int(lines[0])
        ky = int(lines[1])
        if not (0 <= kx <= 49 and 0 <= ky <= 49):
            return False
        pos = json.loads(lines[2])
        if not isinstance(pos, list) or not (1 <= len(pos) <= 15):
            return False
        seen = set()
        for p in pos:
            if not isinstance(p, list) or len(p) != 2:
                return False
            x, y = p
            if not (isinstance(x, int) and isinstance(y, int)):
                return False
            if not (0 <= x <= 49 and 0 <= y <= 49):
                return False
            if (x, y) == (kx, ky):
                return False
            if (x, y) in seen:
                return False
            seen.add((x, y))
        return True
    except Exception:
        return False


def ref(inp):
    lines = inp.split("\n")
    kx = int(lines[0])
    ky = int(lines[1])
    pos = [tuple(p) for p in json.loads(lines[2])]
    n = len(pos)

    # distance from pawn i (or knight start, index n) to every pawn j
    start_bfs = _bfs(kx, ky)
    dist = [[0] * n for _ in range(n + 1)]
    for j in range(n):
        dist[n][j] = start_bfs[pos[j][0]][pos[j][1]]
    for i in range(n):
        bi = _bfs(pos[i][0], pos[i][1])
        for j in range(n):
            dist[i][j] = bi[pos[j][0]][pos[j][1]]

    full = (1 << n) - 1

    @lru_cache(maxsize=None)
    def f(mask, last):
        # mask: remaining pawns; last: knight's current position index (n = start)
        if mask == 0:
            return 0
        removed = n - bin(mask).count("1")
        alice_turn = (removed % 2 == 0)
        best = None
        for j in range(n):
            if mask >> j & 1:
                val = dist[last][j] + f(mask & ~(1 << j), j)
                if best is None:
                    best = val
                elif alice_turn:
                    best = max(best, val)
                else:
                    best = min(best, val)
        return best

    return json.dumps(f(full, n))
